// === Tab: Triangular_grid ===
var rainbowFill;

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();
  // noLoop() removed for animation

  rainbowFill = rainbowFiller(0.1, 0.9, /*hue*/
                              40, 60, /*saturation*/
                              70, 90, /*brightness*/
                              30, 50 );/*hue*/
}

function draw() {
  background(220);

  let ref = floor(min(height, width)/24);
  fillingGrid(8*ref, 0.9);
  fillingGrid(4*ref, 0.8);
  fillingGrid(2*ref, 0.8);
  fillingGrid(ref, 0.9);
}

function mouseClicked() {
  redraw();
}

function fillingGrid(r, a) {
  grid(r, -1, -1, ceil(width/r), ceil(height/(r*sin(60))), 0.9);
}

// 1 2
// 3 4
// pair row: \/\ 123 234
//  odd row: /\/ 134 124
function grid(a, m0, n0, m, n, r) {
  for (let i = m0; i < m; ++i) {
    for (let j = n0; j < n; j += 1) {
      let p1 = edge(a, i, j);
      let p2 = edge(a, i+1, j);
      let p3 = edge(a, i, j+1);
      let p4 = edge(a, i+1, j+1);

      randomTile(p1, p2,j % 2 == 0 ? p3 : p4, r);
      randomTile(j % 2 == 0 ? p2 : p1 , p3, p4, r);        
    }
  }
}


function edge(a, i, j) {
  let x = j % 2 == 0 ? a*i : a*cos(60) + a*i;
  let y = a*sin(60)*j;
  return {x: x, y: y};
}

function randomTile(p1, p2, p3, r) {
  rainbowFill(p1);
  if (random() > r) {
    tile(p1, p2, p3);
  }
}

function tile(p1, p2, p3) {
  triangle(p1.x, p1.y,
           p2.x, p2.y,
           p3.x, p3.y);
}

function rainbowFiller(minHueFactor, maxHueFactor,
                      minSaturation, maxSaturation,
                      minBrightness, maxBrightness,
                      minAlpha, maxAlpha) {

  return function(p) {
    let minHue = map(p.x, minHueFactor*width, maxHueFactor*width, 0, 360);
    let maxHue = map(p.y, minHueFactor*height, maxHueFactor*height, 0, 360);
    let hue = random(minHue, maxHue);
    let saturation = random(minSaturation, maxSaturation);
    let brightness = random(minBrightness, maxBrightness);
    let alpha = random(minAlpha, maxAlpha);
    fill(hue, saturation, brightness, alpha);
  };
};
